/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  width: min(42rem, calc(100% - 2 * var(--gap)));
  margin: clamp(1rem, 5vw, 3.5rem) auto;
  padding: clamp(1rem, 4vw, 2rem);
  border-block-start: 4px solid var(--accent);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1 {
  margin: 0;
  font-size: clamp(1.5rem, 4vw, 2rem);
  line-height: 1.15;
}

.sheet > h1 + p {
  margin: 0.625rem 0 0;
  color: var(--subtle);
}

.sheet form {
  margin-block-start: 1.5rem;
}

.sheet label {
  display: block;
  margin-block: var(--gap) 0.375rem;
  font-weight: 600;
}

.sheet input,
.sheet select {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--subtle);
  border-radius: calc(var(--radius) / 2);
  background: var(--paper);
  color: var(--ink);
}

.sheet input[aria-invalid=\"true\"] {
  border-color: var(--danger);
  box-shadow: inset 0 0 0 1px var(--danger);
}

.sheet [role=\"alert\"] {
  margin: var(--gap) 0 0;
  padding: 0.625rem 0.75rem;
  border-inline-start: 3px solid currentColor;
  background: color-mix(in srgb, var(--danger) 7%, var(--paper));
  color: var(--danger);
  font-weight: 600;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-block-start: 1.5rem;
}

.sheet button {
  max-width: 100%;
  min-height: 44px;
  padding: 0.625rem 0.875rem;
  border: 1px solid var(--subtle);
  border-radius: calc(var(--radius) / 2);
  background: var(--paper);
  color: var(--ink);
  font-weight: 600;
  line-height: 1.35;
  white-space: normal;
  overflow-wrap: anywhere;
}

.sheet :is([data-primary], #confirm) {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.sheet button:hover {
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

.sheet :is(input, select, button):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sheet [role=\"status\"] {
  margin: 1.5rem 0 0;
  padding-block-start: var(--gap);
  border-block-start: 1px solid var(--line);
  color: var(--subtle);
  overflow-wrap: anywhere;
}

.sheet dialog {
  width: min(28rem, calc(100% - 2 * var(--gap)));
  padding: clamp(1rem, 4vw, 1.5rem);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet dialog h2 {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.25;
}

.sheet dialog p {
  margin: 0.75rem 0 var(--gap);
}

.sheet dialog button + button {
  margin-inline-start: 0.375rem;
}

@media (max-width: 36rem) {
  .actions {
    flex-direction: column;
  }
}
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import fs from 'node:fs';
import assert from 'node:assert/strict';
const read = (id) => JSON.parse(fs.readFileSync('visits/' + id + '.json')).timeline.map(({state}) => state);
const [mobile, preview, desktop] = [\"69ab632a-cae9-4949-bd2f-9f556d79ad03\",\"3767c81f-2f61-48ea-971f-7a326d9fc8c4\",\"18c8f479-14e2-43cc-b730-c190861de2b8\"].map(read);
for (const [states, width] of [[mobile,390],[preview,390],[desktop,1180]]) {
  for (const state of states.slice(1)) {
    const {page, elements} = state.geometry;
    assert.equal(state.width, width);
    assert.equal(page, width);
    const primary = elements.find(({text,tag}) => tag === 'BUTTON' && text === 'Review proposed notification preferences');
    assert.equal(primary.client, primary.scroll);
    assert(primary.x >= 0 && primary.x + primary.w <= width && primary.h >= 44);
  }
}
assert.deepEqual(mobile.slice(2,6).map(({focus})=>focus.id || focus.text), ['email','rate','Review proposed notification preferences','Restore saved values']);
assert.equal(mobile[4].geometry.elements.find(e=>e.text===mobile[4].focus.text).outline, 'solid 2px');
assert.equal(mobile.at(-1).focus.id, 'email');
assert.equal(mobile.at(-1).fields[0].invalid, 'true');
assert(mobile.at(-1).status.includes('Enter a complete email address before reviewing these settings.'));
assert.equal(preview.at(-1).dialog.length, 1);
assert.equal(preview.at(-1).focus.id, 'cancel');
assert.equal(preview.at(-1).fields[0].invalid, 'false');
assert.equal(desktop[6].dialog.length, 1);
assert.equal(desktop[7].dialog.length, 0);
assert.equal(desktop[7].focus.text, 'Review proposed notification preferences');
assert.equal(desktop[8].dialog.length, 1);
assert.equal(desktop[9].dialog.length, 0);
assert.equal(desktop[11].status[0], 'duty@example.test / Daily');
assert.equal(desktop[13].fields[0].value, 'ops@example.test');
console.log('Viewport widths, primary button, keyboard order, error, preview, Cancel, Escape, Confirm and Restore passed.');
EOF
sha256sum dist/index.html dist/form.js dist/tokens.css"

