/bin/bash -lc 'set -o pipefail
TMPDIR="$PWD" node --input-type=module - '"'[{\"op\":\"width\",\"width\":390,\"height\":844},{\"op\":\"key\",\"key\":\"Tab\"},{\"op\":\"key\",\"key\":\"Tab\"},{\"op\":\"key\",\"key\":\"Tab\"},{\"op\":\"key\",\"key\":\"Enter\"}]' <<'EOF' | awk 'NR == 1 || /"'^visits'"\\//'
import { readFile } from 'node:fs/promises';
import assert from 'node:assert/strict';
const source = await readFile('visit.mjs','utf8');
const needle = 'windowsVirtualKeyCode:keys[a.key],modifiers:a.shift?8:0';
assert(source.includes(needle));
const withEnterText = source.replace(needle, 'windowsVirtualKeyCode:keys[a.key],text:type===\"keyDown\"&&a.key===\"Enter\"?\"\\\\r\":\"\",modifiers:a.shift?8:0');
await import('data:text/javascript;base64,' + Buffer.from(withEnterText).toString('base64'));
EOF"

